service-call.in-map:
{workEffortId:workEffortId, modules:(modules ?? []),
                    estimateUnit:estimateUnit, statusFlowId:statusFlowId, repositoryChoice:(repositoryChoice || 'none'), repositoryId:repositoryId,
                    linkRepositoryId:linkRepositoryId, docsChoice:(docsChoice || 'none')}

actions.script:
if (!draftProject) return
const settings = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings').parameters({workEffortId: workEffortId}).call()?.settings || {}
const linked = Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitRepository').condition('workEffortId', workEffortId)
        .conditionDate('fromDate', 'thruDate', null).list()).map((row) => row.repositoryId)
linkedText = linked.join(', ')
docsSpaceId = settings.WstDocsWikiSpace || ''
modulesValue = {workEffortId: workEffortId, modules: String(settings.WstModules || '').split(',').filter((key) => key),
    estimateUnit: settings.WstEstimateUnit || 'hours', statusFlowId: draftProject.statusFlowId || 'Default', repositoryChoice: 'none',
    repositoryId: String(workEffortId).toLowerCase(), docsChoice: 'none'}
// the repositories the user may view, to link one (none without git hosting in the build)
repositoryOptions = []
ec.message.pushErrors()
try {
    repositoryOptions = Array.from(ec.service.sync().name('org.moqui.git.GitServices.find#GitRepositories').parameters({pageNoLimit: true}).call()?.repositoryList || [])
            .filter((repo) => !linked.includes(repo.repositoryId)).map((repo) => ({key: repo.repositoryId, text: repo.repositoryId + (repo.description ? ' · ' + repo.description : '')}))
} catch (err) {
    ec.logger.warn('New project modules: the repositories are not listed: ' + err)
} finally { ec.message.clearErrors(); ec.message.popErrors() }
